package com.crewbeat.hondabox.tests;
import com.crewbeat.hondabox.*;
import android.content.res.AssetManager;
import java.io.*;
import org.json.*;
final class RevisionTests {
 private int checks;private void check(String name,boolean good){if(!good)throw new AssertionError(name);checks++;}
 private void raw(ProbeState s,int type,int... p){int[] a=new int[p.length+4];a[0]=46;a[1]=type;a[2]=p.length;int sum=type+p.length;for(int i=0;i<p.length;i++){a[i+3]=p[i];sum+=p[i];}a[a.length-1]=(~sum)&255;s.event(1019,a,null,null);}
 private void text(ProbeState s,int kind,String text){int[] a=new int[text.length()+1];a[0]=kind;for(int i=0;i<text.length();i++)a[i+1]=text.charAt(i);raw(s,7,a);}
 private ProbeState state(){ProbeState s=new ProbeState();s.newSession();s.running(true);s.status("test","",true);s.event(1000,new int[]{6291908},null,null);raw(s,3,129,10);return s;}
 int run(AssetManager assets)throws Exception {
 check("embedded NUL separates fields",BsjText.decode(new int[]{50,0,82,69,71,73,79,78,65,76,32,79,70,70,0},0).text.equals("2 REGIONAL OFF"));
 MediaText scroll=new MediaText();scroll.accept("004 Magic! - Ru>");check("next numbered track replaces unfinished title",scroll.accept("005 Natan feat.>").equals("005 Natan feat.…"));
 scroll.clear();scroll.accept("Babe I'm Gonna>");check("overlapping scroll joined",scroll.accept("Gonna Leave You").equals("Babe I'm Gonna Leave You"));check("complete replacement",scroll.accept("Next song").equals("Next song"));
 ProbeState s=state();raw(s,5,1,0,0,1,1,52,1,20);text(s,4,"Shape of You");check("kind4 is main display",s.snapshot().combinedMediaText().contains("Shape of You"));String time=s.snapshot().cdTime();raw(s,5,0,0,0,0,0,0,0,0);check("blank display does not clear CD",s.snapshot().cdNumber(101).equals("134")&&s.snapshot().cdTime().equals(time));text(s,4,"");check("TITLE blank keeps text",s.snapshot().combinedMediaText().contains("Shape of You"));check("overlay snapshot has callback time",s.overlaySnapshot().lastEvent>0);
 TrackChange track=new TrackChange();check("no initial toast",track.update(s.snapshot(),1000,false)==null);raw(s,5,1,0,0,1,1,53,0,0);check("no old title on new track",s.snapshot().combinedMediaText().equals("—"));check("wait for title",track.update(s.snapshot(),2000,false)==null);text(s,4,"New song");check("new track toast",track.update(s.snapshot(),2700,false).equals("New song"));text(s,4,"New song part");check("text rotation not new track",track.update(s.snapshot(),4000,false)==null);raw(s,5,1,9,0,0,0,0,0,0);check("No Data clears media",s.snapshot().combinedMediaText().equals("—"));
 ProbeState radio=state();raw(radio,3,128,10);raw(radio,4,1,0,241,1,1);TrackChange station=new TrackChange();check("radio initial station has no toast",station.update(radio.snapshot(),1000,false)==null);raw(radio,4,1,0,251,2,1);check("station change debounced",station.update(radio.snapshot(),2000,false)==null);String fm=station.update(radio.snapshot(),2700,false);check("FM station toast includes band and units",fm!=null&&fm.contains("FM1")&&fm.contains("100.00"));raw(radio,4,4,0,9,1,1);check("AM band change debounced",station.update(radio.snapshot(),3000,false)==null);String am=station.update(radio.snapshot(),3700,false);check("AM band change shows station toast",am!=null&&am.contains("AM1")&&am.contains("603"));check("unchanged station has no repeat toast",station.update(radio.snapshot(),5000,false)==null);
 MenuBrowser browser=new MenuBrowser();browser.accept(2,new String[]{"","Artists",""});browser.accept(2,new String[]{"","01:Abba",""});browser.accept(2,new String[]{"","02:Queen",""});check("received indexed list",browser.snapshot(new String[]{"","02:Queen",""}).size()==2);browser.accept(2,new String[]{"","Albums",""});browser.accept(2,new String[]{"","01:Revival",""});check("different category isolated",browser.snapshot(new String[]{"","01:Revival",""}).size()==1);
 ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(InputStream in=assets.open("device-logs-v086.json")){byte[] b=new byte[8192];for(int n;(n=in.read(b))!=-1;)bytes.write(b,0,n);}JSONArray logs=new JSONArray(bytes.toString("UTF-8"));boolean regional=false,tp=false,clock=false,center=false;int frames=0;
 for(int i=0;i<logs.length();i++){ProbeState replay=state();long session=-1;JSONArray chunks=logs.getJSONObject(i).getJSONArray("chunks");for(int j=0;j<chunks.length();j++){JSONObject c=chunks.getJSONObject(j);if(c.getLong("session")!=session){session=c.getLong("session");replay=state();}String[] hex=c.getString("hex").split(" ");int[] a=new int[hex.length];for(int k=0;k<a.length;k++)a[k]=Integer.parseInt(hex[k],16);replay.event(1019,a,null,null);ProbeState.Snapshot snap=replay.overlaySnapshot();String menu=snap.menu().replaceAll("\\s+"," ");regional|=menu.contains("REGIONAL OFF");tp|=menu.contains("AUTO TP ON");clock|=menu.contains("CLOCK")&&menu.contains("12H");center|=MenuListModel.from(snap).items.toString().contains("CENTER");frames++;}}
 check("real logs replayed",frames>1000);check("recorded RDS regional",regional);check("recorded RDS AUTO TP",tp);check("recorded clock value",clock);check("CENTER menu",center);
 return checks;
 }
}
